package io.github.astelev.around_planet.space;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class ForecastAndNavballTest {
 @Test void oneTurnIsDefaultAndLongerSearchKeepsClosedGeometryButExtendsTime(){var sys=new CelestialSystem(20000,4e9,0);double radius=30000;var orbit=new SpaceTrajectory(CelestialSystem.EARTH,0,new SpaceState(new SpaceVector(radius,0,0),new SpaceVector(0,-Math.sqrt(sys.earthMu()/radius),0)),sys.earthMu());double period=EllipticArc.of(orbit.initial(),orbit.mu()).period();var one=ManeuverPreview.create(orbit,0,List.of(),20000,2000,sys);var three=ManeuverPreview.create(orbit,0,List.of(),20000,2000,sys,6,3);assertEquals(Math.round(period*20),one.segments().getLast().validUntil());assertEquals(Math.round(period*60),three.segments().getLast().validUntil());assertTrue(three.segments().getLast().points().getFirst().position().subtract(three.segments().getLast().points().getLast().position()).length()<1e-5);var target=new SpaceTrajectory(CelestialSystem.EARTH,0,sys.moon(0),sys.earthMu());var shortPrediction=RendezvousMath.predictPatched(orbit,one,target,0,20000,2000,sys,CelestialSystem.EARTH,true,6,1);var longPrediction=RendezvousMath.predictPatched(orbit,three,target,0,20000,2000,sys,CelestialSystem.EARTH,true,6,3);assertEquals(one.segments().getLast().validUntil(),shortPrediction.until());assertEquals(three.segments().getLast().validUntil(),longPrediction.until());assertTrue(longPrediction.approaches().stream().anyMatch(a->a.tick()>shortPrediction.until()),"Later-turn conjunction was not searched");}
 @Test void forecastWindowRejectsInvalidCountsAndHandlesOpenMotion(){var line=new SpaceTrajectory("free",0,new SpaceState(new SpaceVector(50000,0,0),new SpaceVector(100,0,0)),0);assertEquals(3600,ForecastWindow.seconds(line,0,1));assertEquals(10800,ForecastWindow.seconds(line,0,3));assertThrows(IllegalArgumentException.class,()->ForecastWindow.seconds(line,0,0));assertThrows(IllegalArgumentException.class,()->ForecastWindow.seconds(line,0,33));}
 @Test void compassMatchesRotatingPlanetChartAndRemainsDefinedAtPoles(){var planet=new PlanetGeometry(65536,65536);var spin=new PlanetSpin(.7,PlanetSpin.OMEGA);for(double x:new double[]{-35000,0,10245})for(double z:new double[]{-17000,0,17000}){var expected=spin.frame(planet,x,z);var actual=CardinalDirections.at(spin.position(planet,x,500,z));assertTrue(actual.east().subtract(expected.east()).length()<1e-8);assertTrue(actual.south().subtract(expected.south()).length()<1e-8);}for(int sign:new int[]{-1,1}){var pole=new SpaceVector(0,0,sign);var frame=CardinalDirections.at(pole);assertEquals(1,frame.east().length(),1e-10);assertEquals(0,frame.south().dot(pole),1e-10);}}
 @Test void largerCornerNavballLeavesTelemetryToItsLeft(){for(int[] size:new int[][]{{320,180},{427,240},{1280,720}})for(float scale:new float[]{.5f,1,2}){var layout=NavballLayout.of(size[0],size[1],scale,0,0,6);assertTrue(layout.x()+layout.radius()<=size[0]-8);assertTrue(layout.y()+layout.radius()<=size[1]-18);assertTrue(layout.textRight()<layout.x()-layout.radius());assertTrue(layout.textTop()>=4);}assertTrue(NavballLayout.of(427,240,1,0,0,6).radius()>38);}
 @Test void rendezvousGlyphsAreNearVesselOnly(){var ship=UUID.randomUUID();assertTrue(NavballLayout.targetMarkers(true,ship,39999.9));assertFalse(NavballLayout.targetMarkers(true,ship,40000));assertFalse(NavballLayout.targetMarkers(true,ship,100000));assertFalse(NavballLayout.targetMarkers(true,CelestialSystem.MOON_ID,1));assertFalse(NavballLayout.targetMarkers(true,CelestialSystem.EARTH_ID,1));assertFalse(NavballLayout.targetMarkers(false,ship,1));assertFalse(NavballLayout.targetMarkers(true,ship,Double.NaN));}
 @Test void maximalCoOrbitalForecastDoesNotExhaustTheEncounterBudget(){var sys=new CelestialSystem(20000,4e9,0);double angle=2*Math.asin((sys.soi()+1)/(2*sys.distance())),speed=Math.sqrt(sys.earthMu()/sys.distance());var path=new SpaceTrajectory(CelestialSystem.EARTH,0,new SpaceState(new SpaceVector(sys.distance()*Math.cos(angle),sys.distance()*Math.sin(angle),0),new SpaceVector(speed*Math.sin(angle),-speed*Math.cos(angle),0)),sys.earthMu());assertEquals(-1,PatchedConics.transition(path,0,Math.round(sys.period()*ForecastWindow.MAX_TURNS*20),sys));}
}
